with base as (select * from payments where order_id in (11, 14, 23, 26) and status = 'FAILED'), payments_stats as (select case when status in ('SUCCESS', 'FAILED') then 'group_a' else 'other' end as status_group, count(*) as total_count from base group by case when status in ('SUCCESS', 'FAILED') then 'group_a' else 'other' end) select * from payments_stats order by total_count desc, status_group desc limit 5
